def upgrade() -> None:
    op.execute(
        """
        CREATE TABLE nexus.imagenes (
          id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
          nombre     text NOT NULL CHECK (char_length(nombre) BETWEEN 1 AND 200),
          tipo       text NOT NULL CHECK (tipo IN ('image/png', 'image/jpeg', 'image/gif')),
          datos      bytea NOT NULL,
          tamano     integer NOT NULL CHECK (tamano BETWEEN 1 AND 1500000),
          ejemplo    boolean NOT NULL DEFAULT false,
          creado_en  timestamptz NOT NULL DEFAULT now(),
          CHECK (octet_length(datos) = tamano)
        );
        ALTER TABLE nexus.plantillas
          ADD COLUMN predeterminada boolean NOT NULL DEFAULT false,
          ADD COLUMN categoria text NOT NULL DEFAULT 'Propia' CHECK (char_length(categoria) <= 60),
          ADD COLUMN descripcion text NOT NULL DEFAULT '' CHECK (char_length(descripcion) <= 300);
        DO $$
        BEGIN
          IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'nexus_app') THEN
            GRANT SELECT, INSERT, UPDATE, DELETE ON nexus.imagenes TO nexus_app;
          END IF;
        END $$;
        """
    )
    conn = op.get_bind()
    for ident, (nombre, b64) in IMAGENES.items():
        datos = base64.b64decode(b64)
        conn.execute(
            text(
                "INSERT INTO nexus.imagenes(id,nombre,tipo,datos,tamano,ejemplo) "
                "VALUES (:id,:n,'image/png',:d,:t,true) ON CONFLICT (id) DO NOTHING"
            ),
            {"id": ident, "n": nombre, "d": datos, "t": len(datos)},
        )
    for t in PLANTILLAS:
        conn.execute(
            text(
                "INSERT INTO nexus.plantillas(nombre,asunto,cuerpo,formato,cuerpo_html,"
                "predeterminada,categoria,descripcion) "
                "VALUES (:nombre,:asunto,:cuerpo,:formato,:cuerpo_html,true,:categoria,:descripcion)"
            ),
            t,
        )


def downgrade() -> None:
    op.execute(
        """
        DELETE FROM nexus.plantillas WHERE predeterminada;
        ALTER TABLE nexus.plantillas DROP COLUMN predeterminada, DROP COLUMN categoria,
          DROP COLUMN descripcion;
        DROP TABLE nexus.imagenes;
        """
    )
